    "title": "GLM 唐杰公开信，万亿智谱继续摸高\\n\\n前天智谱创始人唐杰发布了主题为《巨浪已来》的内部信（公开信）。唐杰阐述了他和智谱对 AGI 的理解，以及，为什么上市之后，依然要把资源押注在最不确定的地方。全文很长，我放墨问了：\\n\\n巨浪已来——致每一位智谱人和关心人工智能未来的伙\\n\\n巨浪、摸高、AGI，都是信里的关键词，不过这些更多是情绪和概念，唐杰并没有一直停留在云端，他谈了三件事儿，也就是公开信里的三座山峰。\\n\\n长程任务、自治智能体、自我进化。翻译成工程语言，就是让模型从回答问题，走向复杂长任务",
